import { ReactNode } from "react";

export default function Badge({ children }: { children: ReactNode }) {
  return (
    <span className="inline-flex items-center gap-1 rounded-full bg-gray-100 text-gray-700 text-xs font-semibold uppercase px-3 py-1">
      <span className="w-1.5 h-1.5 bg-gray-700 rounded-full"></span>
      {children}
    </span>
  );
}
