import { ReactNode } from "react";

export type ButtonProps = {
  variant?: "primary" | "outline";
  children: ReactNode;
  className?: string;
} & React.ButtonHTMLAttributes<HTMLButtonElement>;

export default function Button({
  variant = "primary",
  children,
  className = "",
  ...rest
}: ButtonProps) {
  const base =
    "inline-flex items-center justify-center px-6 py-3 rounded text-sm font-medium transition-colors";
  const variants: Record<string, string> = {
    primary: "bg-gray-900 text-white border border-gray-900 hover:bg-gray-800",
    outline:
      "bg-transparent text-gray-900 border border-gray-300 hover:bg-gray-100",
  };

  return (
    <button className={`${base} ${variants[variant]} ${className}`} {...rest}>
      {children}
    </button>
  );
}
